5418  format_expand1(struct format_expand_state *es, const char *fmt)
  5419  {
  5420          struct format_tree      *ft = es->ft;
  5421          char                    *buf, *out, *name;
  5422          const char              *ptr, *s, *style_end = NULL;
  5423          size_t                   off, len, n, outlen;
  5424          int                      ch, brackets;
  5425          char                     expanded[8192];
  5426
  5427          if (fmt == NULL || *fmt == '\0')
  5428                  return (xstrdup(""));
  5429
  5430          if (es->loop == FORMAT_LOOP_LIMIT) {
  5431                  format_log(es, "reached loop limit (%u)", FORMAT_LOOP_LIMIT);
  5432                  return (xstrdup(""));
  5433          }
  5434          es->loop++;
  5435
  5436          format_log(es, "expanding format: %s", fmt);
  5437
  5438          if ((es->flags & FORMAT_EXPAND_TIME) && strchr(fmt, '%') != NULL) {
  5439                  if (es->time == 0) {
  5440                          es->time = time(NULL);
  5441                          localtime_r(&es->time, &es->tm);
  5442                  }
  5443                  if (format_strftime(expanded, sizeof expanded, fmt,
  5444                      &es->tm) == 0) {
  5445                          format_log(es, "format is too long");
  5446                          return (xstrdup(""));
  5447                  }
  5448                  if (format_logging(ft) && strcmp(expanded, fmt) != 0)
  5449                          format_log(es, "after time expanded: %s", expanded);
  5450                  fmt = expanded;
  5451          }
  5452
  5453          len = 64;
  5454          buf = xmalloc(len);
  5455          off = 0;
  5456
  5457          while (*fmt != '\0') {
  5458                  if (*fmt != '#') {
  5459                          while (len - off < 2) {
  5460                                  buf = xreallocarray(buf, 2, len);
  5461                                  len *= 2;
  5462                          }
  5463                          buf[off++] = *fmt++;
  5464                          continue;
  5465                  }
  5466                  if (*fmt++ == '\0')
  5467                          break;
  5468
  5469                  ch = (u_char)*fmt++;
  5470                  switch (ch) {
  5471                  case '(':
  5472                          brackets = 1;
  5473                          for (ptr = fmt; *ptr != '\0'; ptr++) {
  5474                                  if (*ptr == '(')
  5475                                          brackets++;
  5476                                  if (*ptr == ')' && --brackets == 0)
  5477                                          break;
  5478                          }
  5479                          if (*ptr != ')' || brackets != 0)
  5480                                  break;
  5481                          n = ptr - fmt;
  5482
  5483                          name = xstrndup(fmt, n);
  5484                          format_log(es, "found #(): %s", name);
  5485
  5486                          if ((ft->flags & FORMAT_NOJOBS) ||
  5487                              (es->flags & FORMAT_EXPAND_NOJOBS)) {
  5488                                  out = xstrdup("");
  5489                                  format_log(es, "#() is disabled");
  5490                          } else {
  5491                                  out = format_job_get(es, name);
  5492                                  format_log(es, "#() result: %s", out);
  5493                          }
  5494                          free(name);
  5495
  5496                          outlen = strlen(out);
  5497                          while (len - off < outlen + 1) {
  5498                                  buf = xreallocarray(buf, 2, len);
  5499                                  len *= 2;
  5500                          }
  5501                          memcpy(buf + off, out, outlen);
  5502                          off += outlen;
  5503
  5504                          free(out);
  5505
  5506                          fmt += n + 1;
  5507                          continue;
  5508                  case '{':
  5509                          ptr = format_skip((char *)fmt - 2, "}");
  5510                          if (ptr == NULL)
  5511                                  break;
  5512                          n = ptr - fmt;
  5513
  5514                          format_log(es, "found #{}: %.*s", (int)n, fmt);
  5515                          if (format_replace(es, fmt, n, &buf, &len, &off) != 0)
  5516                                  break;
  5517                          fmt += n + 1;
  5518                          continue;
  5519                  case '[':
  5520                  case '#':
  5521                          /*
  5522                           * If ##[ (with two or more #s), then it is a style and
  5523                           * can be left for format_draw to handle.
  5524                           */
  5525                          ptr = fmt - (ch == '[');
  5526                          n = 2 - (ch == '[');
  5527                          while (*ptr == '#') {
  5528                                  ptr++;
  5529                                  n++;
  5530                          }
  5531                          if (*ptr == '[') {
  5532                                  style_end = format_skip(fmt - 2, "]");
  5533                                  format_log(es, "found #*%zu[", n);
  5534                                  while (len - off < n + 2) {
  5535                                          buf = xreallocarray(buf, 2, len);
  5536                                          len *= 2;
  5537                                  }
  5538                                  memcpy(buf + off, fmt - 2, n + 1);
  5539                                  off += n + 1;
  5540                                  fmt = ptr + 1;
  5541                                  continue;
  5542                          }
  5543                          /* FALLTHROUGH */
  5544                  case '}':
  5545                  case ',':
  5546                          format_log(es, "found #%c", ch);
  5547                          while (len - off < 2) {
  5548                                  buf = xreallocarray(buf, 2, len);
  5549                                  len *= 2;
  5550                          }
  5551                          buf[off++] = ch;
  5552                          continue;
  5553                  default:
  5554                          s = NULL;
  5555                          if (fmt > style_end) { /* skip inside #[] */
  5556                                  if (ch >= 'A' && ch <= 'Z')
  5557                                          s = format_upper[ch - 'A'];
  5558                                  else if (ch >= 'a' && ch <= 'z')
  5559                                          s = format_lower[ch - 'a'];
  5560                          }
  5561                          if (s == NULL) {
  5562                                  while (len - off < 3) {
  5563                                          buf = xreallocarray(buf, 2, len);
  5564                                          len *= 2;
  5565                                  }
  5566                                  buf[off++] = '#';
  5567                                  buf[off++] = ch;
  5568                                  continue;
  5569                          }
  5570                          n = strlen(s);
  5571                          format_log(es, "found #%c: %s", ch, s);
  5572                          if (format_replace(es, s, n, &buf, &len, &off) != 0)
  5573                                  break;
  5574                          continue;
  5575                  }
  5576
  5577                  break;
  5578          }
  5579          buf[off] = '\0';
  5580
  5581          format_log(es, "result is: %s", buf);
  5582          es->loop--;
  5583
  5584          return (buf);
  5585  }
